mapper.select:
SELECT * FROM inspection_issue
WHERE user_id = #{userId} AND is_deleted = 0

    AND created_at >= #{startTime}


    AND created_at < #{endTime}


    AND location LIKE CONCAT('%', #{location}, '%')

ORDER BY created_at DESC, id DESC

SELECT * FROM inspection_issue WHERE user_id = #{userId} AND is_deleted = 0 AND id IN
#{id}
ORDER BY created_at ASC, id ASC

mapper.update:
UPDATE inspection_issue
SET location = #{location}, reason = #{reason}, measure = #{measure}
WHERE id = #{id} AND user_id = #{userId} AND is_deleted = 0
